pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 value, address actor) public {
        ts = bound(ts, 1, type(uint256).max / 2);
        value = bound(value, 0, type(uint256).max / 2);
        vm.assume(actor != address(0) && actor != address(c));
        vm.warp(ts);
        vm.deal(actor, value);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: value}("");
        // Rule: whenever a fallback call succeeds, the recorded pastBlockTime
        // must be strictly greater than the block.timestamp at which it succeeded
        // (C stores t + 1; the mutant stores t, which is not > t).
        assertTrue(!ok || c.pastBlockTime() > block.timestamp);
    }
}
